-- Converge discussion board. Run this once in the Supabase SQL editor.
-- Generated by scripts/build-forum-sql.mjs; word list from LDNOOBW (CC-BY-4.0).

create table if not exists public.banned_words (
  word text primary key,
  norm text not null,
  squeezed text not null
);

-- lowercase, strip accents, undo leetspeak, keep letters, join spaced-out single letters
create or replace function public.converge_norm(t text) returns text
language plpgsql immutable as $$
declare x text; tok text; res text := ''; prev_single boolean := false;
begin
  x := lower(coalesce(t, ''));
  x := translate(x, 'àáâãäåèéêëìíîïòóôõöùúûüñç', 'aaaaaaeeeeiiiiooooouuuunc');
  x := translate(x, '01!|3@457+89$', 'oiiieaasttbgs');
  x := btrim(regexp_replace(x, '[^a-z]+', ' ', 'g'));
  -- join runs of single letters: "f u c k" -> "fuck"
  foreach tok in array string_to_array(x, ' ') loop
    continue when tok = '';
    if length(tok) = 1 and prev_single then res := res || tok;
    else res := res || case when res = '' then '' else ' ' end || tok; end if;
    prev_single := length(tok) = 1;
  end loop;
  return res;
end $$;

create or replace function public.converge_is_profane(t text) returns boolean
language plpgsql stable as $$
declare n text; s text; j text; r text; -- roots below are blocked even inside longer words
begin
  n := public.converge_norm(t);
  s := regexp_replace(n, '(.)\1+', '\1', 'g');
  j := replace(s, ' ', '');
  -- stretched spellings: squeeze only the words that repeat a letter, so "but" never matches "butt"
  select coalesce(string_agg(regexp_replace(w, '(.)\1+', '\1', 'g'), ' '), '') into r from unnest(string_to_array(n, ' ')) w where w ~ '(.)\1';
  return exists (
    select 1 from public.banned_words b
    where position(' ' || b.norm || ' ' in ' ' || n || ' ') > 0
       or (position(' ' in b.squeezed) = 0 and position(' ' || b.squeezed || ' ' in ' ' || r || ' ') > 0)
       or (length(b.squeezed) >= 5 and position(' ' in b.squeezed) = 0 and position(b.squeezed in j) > 0)
  ) or j ~ '(fuck|fuk|shit|bitch|nigg|whore|motherf|cocksuck|dickhead|asshole|bastard|retard)';
end $$;

create table if not exists public.forum_posts (
  id bigint generated always as identity primary key,
  ticker text not null check (ticker ~ '^[A-Z.]{1,6}$'),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  display_name text not null check (char_length(display_name) between 2 and 30),
  body text not null check (char_length(btrim(body)) between 1 and 1000),
  created_at timestamptz not null default now()
);
create index if not exists forum_posts_ticker_created on public.forum_posts (ticker, created_at desc);

-- membership tiers: everyone signs up as 'free'; only premium members can post
create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  tier text not null default 'free' check (tier in ('free', 'premium')),
  premium_until timestamptz,
  created_at timestamptz not null default now()
);
alter table public.profiles enable row level security;
drop policy if exists "members read their own profile" on public.profiles;
create policy "members read their own profile" on public.profiles for select to authenticated using (id = auth.uid());
-- no insert/update policies: tiers change only from the dashboard, SQL, or a payment webhook using the service role

create or replace function public.converge_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  return new;
end $$;
drop trigger if exists converge_new_user on auth.users;
create trigger converge_new_user after insert on auth.users for each row execute function public.converge_new_user();

-- master switch: while premium_required is false (testing), every signed-in member counts as premium.
-- Turn the paywall on with: update public.converge_settings set premium_required = true;
create table if not exists public.converge_settings (
  id int primary key default 1 check (id = 1),
  premium_required boolean not null default false
);
alter table public.converge_settings enable row level security;
drop policy if exists "anyone can read settings" on public.converge_settings;
create policy "anyone can read settings" on public.converge_settings for select using (true);

create or replace function public.converge_is_premium(uid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select uid is not null and (
    not coalesce((select premium_required from public.converge_settings where id = 1), false)
    or exists (select 1 from public.profiles p where p.id = uid and p.tier = 'premium' and (p.premium_until is null or p.premium_until > now())));
$$;

alter table public.forum_posts enable row level security;
drop policy if exists "anyone can read posts" on public.forum_posts;
create policy "anyone can read posts" on public.forum_posts for select using (true);
drop policy if exists "signed-in users post as themselves" on public.forum_posts;
create policy "signed-in users post as themselves" on public.forum_posts for insert to authenticated with check (user_id = auth.uid());
drop policy if exists "premium members post as themselves" on public.forum_posts;
drop policy if exists "signed-in users post as themselves" on public.forum_posts;
create policy "premium members post as themselves" on public.forum_posts for insert to authenticated with check (user_id = auth.uid() and public.converge_is_premium(auth.uid()));
drop policy if exists "authors delete their posts" on public.forum_posts;
create policy "authors delete their posts" on public.forum_posts for delete to authenticated using (user_id = auth.uid());

alter table public.banned_words enable row level security; -- not readable through the API

-- block foul language and flooding, server-side
create or replace function public.converge_check_post() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.user_id := auth.uid();
  new.body := btrim(new.body);
  if not public.converge_is_premium(new.user_id) then
    raise exception 'Posting is a Premium feature.' using errcode = 'P0001';
  end if;
  if public.converge_is_profane(new.body) or public.converge_is_profane(new.display_name) then
    raise exception 'Post blocked: please keep the language civil.' using errcode = 'P0001';
  end if;
  if (select count(*) from public.forum_posts where user_id = new.user_id and created_at > now() - interval '1 minute') >= 5 then
    raise exception 'You are posting too fast. Please wait a minute.' using errcode = 'P0001';
  end if;
  return new;
end $$;
drop trigger if exists converge_check_post on public.forum_posts;
create trigger converge_check_post before insert on public.forum_posts for each row execute function public.converge_check_post();

-- account sync: one private document per member (portfolio lots, theses, watchlist, settings)
create table if not exists public.user_state (
  user_id uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  data jsonb not null default '{}'::jsonb,
  device text,
  updated_at timestamptz not null default now(),
  constraint user_state_size check (octet_length(data::text) < 2000000)
);
alter table public.user_state enable row level security;
drop policy if exists "members read their own state" on public.user_state;
create policy "members read their own state" on public.user_state for select to authenticated using (user_id = auth.uid());
drop policy if exists "members create their own state" on public.user_state;
create policy "members create their own state" on public.user_state for insert to authenticated with check (user_id = auth.uid());
drop policy if exists "members update their own state" on public.user_state;
create policy "members update their own state" on public.user_state for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
grant select, insert, update on public.user_state to authenticated;

-- members can delete their own account (posts, profile and synced data go with it)
create or replace function public.converge_delete_me() returns void
language plpgsql security definer set search_path = public, auth as $$
begin
  if auth.uid() is null then raise exception 'Not signed in.' using errcode = 'P0001'; end if;
  delete from auth.users where id = auth.uid();
end $$;
revoke all on function public.converge_delete_me() from public, anon;
grant execute on function public.converge_delete_me() to authenticated;

-- word list
on conflict (word) do nothing;
delete from public.banned_words where length(norm) < 3;
